Rules.InvariantScript:
If(
    !varDrillFromWeekly,
    Set(
        varApprovalWeekStart,
        DateAdd(Today(), -(Weekday(Today(), StartOfWeek.Monday) - 1), "Days")
    )
);
Set(varApprovalStatusFilter, "All");
Set(varDrillFromWeekly, false);
Clear(colHoursUpdates);
Select(Button_ReloadApprovalsWeek);

ForAll(
    colHoursUpdates As UpdateRow,
    Patch(
        'Hours Tracking (Hours)',
        LookUp('Hours Tracking (Hours)', ID = UpdateRow.ID),
        {
            ApprovalStatus_1: UpdateRow.ApprovalStatus_1,
            Approver_Comments: UpdateRow.Approver_Comments
        }
    )
);
Notify("Changes saved", NotificationType.Success);
Clear(colHoursUpdates);
Refresh('Hours Tracking (Hours)');

ClearCollect(
    colApproveAll,
    ForAll(
        Filter(
            colApprovalWeekHours,
            (
                ApprovalStatus_1 = "Pending" ||
                ApprovalStatus_1 = "Rejected"
            ) &&
            (
                IsBlank(varSelectedWeekEmployee) ||
                Employee = varSelectedWeekEmployee
            )
        ) As TargetRow,
        {
            ID: TargetRow.ID,
            ApprovalStatus_1: "Approved"
        }
    )
);
If(
    CountRows(colApproveAll) = 0,
    Notify("No rows to approve in this week", NotificationType.Information),
    Patch('Hours Tracking (Hours)', colApproveAll);
    Notify("Week approved", NotificationType.Success)
);
Clear(colHoursUpdates);
Clear(colApproveAll);
Select(Button_ReloadApprovalsWeek);

With(
    {
        rawTask: Coalesce(ThisItem.Task, ""),
        rawComment: Coalesce(ThisItem.Comments, ""),
        sepPos: Find(" | ", Coalesce(ThisItem.Comments, ""))
    },
    If(
        !IsBlank(rawTask),
        rawTask,
        If(
            IsBlank(rawComment),
            "",
            If(sepPos < 1, rawComment, Left(rawComment, sepPos - 1))
        )
    )
)

With(
    {
        rawTask: Coalesce(ThisItem.Task, ""),
        rawComment: Coalesce(ThisItem.Comments, ""),
        sepPos: Find(" | ", Coalesce(ThisItem.Comments, ""))
    },
    If(
        !IsBlank(rawTask),
        rawComment,
        If(sepPos < 1, "", Mid(rawComment, sepPos + 3))
    )
)

If(
    IsBlank(LookUp(colHoursUpdates, ID = ThisItem.ID)),
    Collect(
        colHoursUpdates,
        {
            ID: ThisItem.ID,
            ApprovalStatus_1: Self.Selected.Value,
            Approver_Comments: ThisItem.Approver_Comments
        }
    ),
    UpdateIf(
        colHoursUpdates,
        ID = ThisItem.ID,
        { ApprovalStatus_1: Self.Selected.Value }
    )
)

If(
    IsBlank(LookUp(colHoursUpdates, ID = ThisItem.ID)),
    Collect(
        colHoursUpdates,
        {
            ID: ThisItem.ID,
            ApprovalStatus_1: ThisItem.ApprovalStatus_1,
            Approver_Comments: Self.Text
        }
    ),
    UpdateIf(
        colHoursUpdates,
        ID = ThisItem.ID,
        { Approver_Comments: Self.Text }
    )
)

Refresh('Hours Tracking (Hours)');
Clear(colApprovalWeekHours);
If(
    varIsSuperAdmin,
    Collect(
        colApprovalWeekHours,
        Filter(
            'Hours Tracking (Hours)',
            ApprovalStatus_1 = "Pending" &&
            Date >= varApprovalWeekStart &&
            Date <= DateAdd(varApprovalWeekStart, 6, "Days")
        )
    );
    Collect(
        colApprovalWeekHours,
        Filter(
            'Hours Tracking (Hours)',
            ApprovalStatus_1 = "Approved" &&
            Date >= varApprovalWeekStart &&
            Date <= DateAdd(varApprovalWeekStart, 6, "Days")
        )
    );
    Collect(
        colApprovalWeekHours,
        Filter(
            'Hours Tracking (Hours)',
            ApprovalStatus_1 = "Rejected" &&
            Date >= varApprovalWeekStart &&
            Date <= DateAdd(varApprovalWeekStart, 6, "Days")
        )
    ),
    Collect(
        colApprovalWeekHours,
        Filter(
            'Hours Tracking (Hours)',
            ApproverID_1 = varMyEmail &&
            ApprovalStatus_1 = "Pending" &&
            Date >= varApprovalWeekStart &&
            Date <= DateAdd(varApprovalWeekStart, 6, "Days")
        )
    );
    Collect(
        colApprovalWeekHours,
        Filter(
            'Hours Tracking (Hours)',
            ApproverID_1 = varMyEmail &&
            ApprovalStatus_1 = "Approved" &&
            Date >= varApprovalWeekStart &&
            Date <= DateAdd(varApprovalWeekStart, 6, "Days")
        )
    );
    Collect(
        colApprovalWeekHours,
        Filter(
            'Hours Tracking (Hours)',
            ApproverID_1 = varMyEmail &&
            ApprovalStatus_1 = "Rejected" &&
            Date >= varApprovalWeekStart &&
            Date <= DateAdd(varApprovalWeekStart, 6, "Days")
        )
    )
);
